CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', answers jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile" ON public.profiles FOR ALL TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (NEW.id, coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER create_profile_after_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.reflections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, event_id integer NOT NULL, event_title text NOT NULL, category text NOT NULL, district text NOT NULL, rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5), answers jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.reflections TO authenticated;
GRANT ALL ON public.reflections TO service_role;
ALTER TABLE public.reflections ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own reflections" ON public.reflections FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.reflection_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, reflection_id uuid REFERENCES public.reflections(id) ON DELETE SET NULL, event_id integer NOT NULL, kind text NOT NULL CHECK (kind IN ('photo','voice')), origin text NOT NULL CHECK (origin IN ('quest','reflection')), question text, path text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), CHECK (split_part(path,'/',1) = user_id::text));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.reflection_media TO authenticated;
GRANT ALL ON public.reflection_media TO service_role;
ALTER TABLE public.reflection_media ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own reflection media" ON public.reflection_media FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND (reflection_id IS NULL OR EXISTS (SELECT 1 FROM public.reflections r WHERE r.id = reflection_id AND r.user_id = auth.uid())));
CREATE TABLE public.memories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, photo_ids uuid[] NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.memories TO authenticated;
GRANT ALL ON public.memories TO service_role;
ALTER TABLE public.memories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own memories" ON public.memories FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE FUNCTION public.validate_memory_photos() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF cardinality(NEW.photo_ids) < 1 OR EXISTS (SELECT 1 FROM unnest(NEW.photo_ids) photo_id WHERE NOT EXISTS (SELECT 1 FROM public.reflection_media m WHERE m.id = photo_id AND m.user_id = NEW.user_id AND m.kind = 'photo')) THEN RAISE EXCEPTION 'Memory photos must belong to this account'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_memory_photos BEFORE INSERT OR UPDATE ON public.memories FOR EACH ROW EXECUTE FUNCTION public.validate_memory_photos();
CREATE POLICY "Private reflection files read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'reflections' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Private reflection files upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'reflections' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Private reflection files delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'reflections' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE INDEX reflections_user_date ON public.reflections(user_id, created_at DESC);
CREATE INDEX reflection_media_user ON public.reflection_media(user_id);
CREATE INDEX memories_user_date ON public.memories(user_id, created_at DESC);